const culturalCapsules=[
 [
  {title:{es:'¿Hay que responder a «irasshaimase»?',en:'Must you reply to “irasshaimase”?'},jp:'いらっしゃいませ',roma:'Irasshaimase',body:{es:'Al entrar en una tienda o cafetería, el personal suele darte esta bienvenida. No es una pregunta: no necesitas contestar verbalmente. Puedes entrar con naturalidad o asentir ligeramente.',en:'Staff often welcome you with this when you enter a shop or café. It is not a question: you do not need to reply verbally. You can simply enter or nod slightly.'},takeaway:{es:'Reconócelo al escucharlo, pero no lo repitas como cliente.',en:'Recognise it when you hear it, but do not repeat it as a customer.'}},
  {title:{es:'¿Cómo llamo al personal?',en:'How do I get staff attention?'},jp:'すみません',roma:'Sumimasen',body:{es:'Cuando necesites pedir algo, «sumimasen» es una manera habitual y educada de llamar la atención. El personal puede estar ocupado: espera a que te atiendan y evita gritar o insistir continuamente.',en:'When you need something, “sumimasen” is a common polite way to get attention. Staff may be busy: wait to be attended to instead of repeatedly shouting.'},takeaway:{es:'Saludar al entrar y pedir ayuda son dos situaciones distintas.',en:'Greeting on arrival and asking for help are different situations.'}}
 ],
 [
  {title:{es:'Reverencias y contacto físico',en:'Bowing and physical contact'},jp:'はじめまして',roma:'Hajimemashite',body:{es:'Al conocer a alguien, una leve inclinación de cabeza puede ser apropiada. No des por hecho que corresponde abrazar, dar dos besos o estrechar la mano: observa a la otra persona y el contexto.',en:'When meeting someone, a small bow or nod can be appropriate. Do not assume a hug, cheek kisses or a handshake is expected: observe the other person and the context.'},takeaway:{es:'La cortesía no exige copiar una reverencia profunda.',en:'Politeness does not require imitating a deep formal bow.'}},
  {title:{es:'Nombres y tratamientos',en:'Names and forms of address'},jp:'さん',roma:'-san',body:{es:'En relaciones no cercanas es frecuente utilizar el apellido con «-san» (por ejemplo, Tanaka-san). No lo añadas a tu propio nombre al presentarte; con amigos o personas que te inviten a usar el nombre de pila, el trato puede cambiar.',en:'With people you do not know closely, surname plus “-san” is common (for example, Tanaka-san). Do not add it to your own name when introducing yourself; closer relationships may use given names.'},takeaway:{es:'El tratamiento depende de la relación, no solo de la traducción de «señor».',en:'Forms of address depend on the relationship, not just the translation of “Mr/Ms”.'}}
 ],
 [
  {title:{es:'Pedir ayuda sin interrumpir bruscamente',en:'Asking without abruptly interrupting'},jp:'すみません',roma:'Sumimasen',body:{es:'Antes de preguntar por una dirección, «sumimasen» ayuda a iniciar la conversación con cortesía. Acércate sin invadir el espacio personal y acepta con naturalidad que alguien no pueda ayudarte.',en:'Before asking for directions, “sumimasen” is a polite way to begin. Avoid invading personal space, and accept that someone may not be able to help.'},takeaway:{es:'Una petición breve y respetuosa suele ser más útil que un discurso largo.',en:'A brief, respectful request is usually more useful than a long speech.'}},
  {title:{es:'¿Y si no entiendo la respuesta?',en:'What if I do not understand the answer?'},jp:'もう一度お願いします',roma:'Mō ichido onegaishimasu',body:{es:'No tienes que fingir que has entendido. Puedes pedir que repitan («mō ichido onegaishimasu») o que hablen más despacio («yukkuri onegaishimasu»). Una respuesta puede incluir gestos o direcciones sencillas.',en:'You do not need to pretend to understand. Ask for repetition (“mō ichido onegaishimasu”) or slower speech (“yukkuri onegaishimasu”). Replies may include gestures and simple directions.'},takeaway:{es:'Pedir aclaración es una destreza comunicativa, no un fracaso.',en:'Asking for clarification is a communication skill, not a failure.'}}
 ]
];
