function hasPractice(activityId){return state.practiceEvents.some(e=>e.lessonId===lessons[state.lesson].id&&e.activityId===activityId);}
function recordPractice(activityId,kind){if(hasPractice(activityId))return;tick();state.practiceEvents.push({lessonId:lessons[state.lesson].id,activityId,kind,completedAt:new Date().toISOString(),activeSecondsAtCompletion:Math.floor(state.activeMs/1000),assessment:'self-reported completion; accuracy and pronunciation not evaluated'});saveIfEnabled();render();}

