function guidedLesson(){
const scenes=guidedPractice[state.lesson].scenes[state.lang];
return '<section class="lesson-section"><p class="eyelabel">'+tr('Situaciones reales · 10–12 min','Real-life situations · 10–12 min')+'</p><h2>'+tr('Piensa → Dilo en voz alta → Comprueba','Think → Say it aloud → Check')+'</h2><p>'+tr('Intenta responder antes de pulsar «Comprobar respuesta». Puede haber varias maneras naturales de decirlo. Escucha las soluciones y marca como practicado solo cuando hayas intentado responder.','Try answering before pressing “Check response”. More than one answer may be natural. Listen to the solutions and mark as practised only after making an attempt.')+'</p>'+
scenes.map((prompt,i)=>{
const solutions=scenarioSolutions[state.lesson][i];
return '<div class="scene"><p><strong>'+(i+1)+'.</strong> '+esc(prompt)+'</p><button class="btn secondary" data-reveal="'+i+'" aria-expanded="false">👁 '+tr('Comprobar respuesta','Check response')+'</button><div class="scene-solution" id="solution-'+i+'" hidden>'+solutions.map((sol,j)=>'<div class="solution-line"><span class="tag">'+(j===0?tr('Recomendada','Recommended'):tr('También natural','Also natural'))+'</span><div class="jp" lang="ja">'+esc(sol.jp)+'</div><div class="roma">'+esc(sol.roma)+'</div><div>'+esc(sol[state.lang])+'</div><button class="speak" data-speak="'+esc(sol.jp)+'" aria-label="'+tr('Escuchar japonés','Listen to Japanese')+'">▶ '+tr('Escuchar','Listen')+'</button></div>').join('')+'</div><div><button class="btn secondary scene-done" data-practice="scene-'+i+'">'+(hasPractice('scene-'+i)?tr('✓ Practicado','✓ Practised'):tr('He practicado esta situación','I practised this situation'))+'</button></div></div>';
}).join('')+
'<p class="tip">'+tr('La práctica se registra como autodeclarada, no como evaluación de pronunciación.','Practice is recorded as self-reported, not as a pronunciation assessment.')+'</p></section>';
}
function trackerPrompt(){
return tr(
`Actúa como mi tutor y analista de japonés para un viaje a Japón. Crea un libro Excel llamado Japanese Learning Tracker con hojas Sesiones, Intentos, Competencias y Objetivos semanales. Sesiones: ID único, fecha, minutos activos, intentos, aciertos y lecciones. Intentos: ID de sesión, fecha, lección, pregunta, competencia, respuesta, respuesta esperada, acierto y número de intento. Competencias: evidencia observada, errores recurrentes y siguiente repaso; nunca marques dominio solo por una respuesta correcta. Objetivos semanales: minutos y días de práctica, distinguiendo lo registrado de lo estimado. Te adjuntaré periódicamente uno o varios JSON con esquema japanese-learning-journey/report-v1 y el Excel actualizado. Valida el esquema, importa todos los intentos, deduplica por sessionId y por intento, importa practiceEvents como prácticas autodeclaradas y audioEvents como solicitudes de audio (sin asumir escucha ni pronunciación), actualiza resúmenes y devuélveme el Excel actualizado para descargar. No inventes prácticas orales ni progresos no registrados. Si no puedes generar Excel, proporciona CSV separados para las cuatro hojas.`,
`Act as my Japanese tutor and learning analyst for a trip to Japan. Create an Excel workbook named Japanese Learning Tracker with sheets Sessions, Attempts, Skills and Weekly Goals. Sessions: unique session ID, date, active minutes, attempts, correct answers and lessons. Attempts: session ID, timestamp, lesson, question, skill, response, expected response, correct and attempt number. Skills: observed evidence, recurring mistakes and next review; never mark mastery based on one right answer. Weekly Goals: minutes and days practised, distinguishing recorded and estimated time. I will attach JSON reports (schema japanese-learning-journey/report-v1) and the latest Excel workbook. Validate schema, import all attempts, deduplicate by sessionId and individual attempt, import practiceEvents as self-reported activity and audioEvents as audio requests (not proof of listening or pronunciation), update summaries, and give me the updated workbook to download. Do not invent speaking practice or unrecorded progress. If you cannot create Excel, supply four CSV files.`);
}

